--
-- Name: check_attacker_defender_different(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.check_attacker_defender_different() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.attacker_id = NEW.defender_id THEN
        RAISE EXCEPTION 'attacker_id dan defender_id tidak boleh sama (character_id: %)', NEW.attacker_id;
    END IF;
    RETURN NEW;
END;
$$;


