--
-- Name: check_transferred_no_revert(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.check_transferred_no_revert() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF OLD.transferred IN ('yes', 'no') AND NEW.transferred = 'pending' THEN
        RAISE EXCEPTION 'transferred tidak boleh diubah kembali ke pending setelah berstatus % (war_id: %, title_id: %, year: %)',
            OLD.transferred, NEW.war_id, NEW.title_id, NEW.year;
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION public.check_transferred_no_revert() OWNER TO postgres;

--
-- Name: prevent_delete_resolved_war(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.prevent_delete_resolved_war() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF EXISTS (
        SELECT 1 FROM War_Contests
        WHERE war_id = OLD.war_id
        AND transferred IN ('yes', 'no')
    ) THEN
        RAISE EXCEPTION 'War % tidak bisa dihapus karena sudah punya war_contests dengan status final (yes/no)', OLD.war_id;
    END IF;
    RETURN OLD;
END;
$$;


ALTER FUNCTION public.prevent_delete_resolved_war() OWNER TO postgres;

--
-- Name: recalc_sub_counties(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.recalc_sub_counties() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    target_title_id VARCHAR(50);
    target_year INT;
BEGIN
    target_title_id := COALESCE(NEW.parent_title_id, OLD.parent_title_id);
    target_year := COALESCE(NEW.year, OLD.year);

    IF target_title_id IS NOT NULL THEN
        UPDATE Title_Snapshot
        SET sub_counties = (
            SELECT COUNT(*) FROM Title_Snapshot
            WHERE parent_title_id = target_title_id AND year = target_year
        )
        WHERE title_id = target_title_id AND year = target_year;
    END IF;

    RETURN COALESCE(NEW, OLD);
END;
$$;


ALTER FUNCTION public.recalc_sub_counties() OWNER TO postgres;

